# --- model call -----------------------------------------------------------


def ask_claude(prompt: str, system: str) -> tuple[str, dict]:
    """One Claude Agent SDK turn, no tools. Returns (text, usage). Runs outside the repo."""
    load_env()
    import claude_agent_sdk

    sdk = neatlogs.wrap(claude_agent_sdk)
    # Blank these so the CLI does not refuse to nest inside a Claude Code session.
    env = {"CLAUDECODE": "", "CLAUDE_CODE_ENTRYPOINT": ""}
    workdir = tempfile.mkdtemp(prefix="firstrun-llm-")

    async def _go() -> tuple[str, dict]:
        options = claude_agent_sdk.ClaudeAgentOptions(
            model=MODEL, effort=EFFORT, allowed_tools=[], max_turns=1,
            setting_sources=[], cwd=workdir, system_prompt=system, env=env,
        )
        text, usage = "", {}
        async for msg in sdk.query(prompt=prompt, options=options):
            if isinstance(msg, claude_agent_sdk.ResultMessage):
                if getattr(msg, "result", None):
                    text = msg.result
                raw = getattr(msg, "usage", None) or {}
                usage = {
                    "input_tokens": int(raw.get("input_tokens", 0) or 0)
                    + int(raw.get("cache_read_input_tokens", 0) or 0)
                    + int(raw.get("cache_creation_input_tokens", 0) or 0),
                    "output_tokens": int(raw.get("output_tokens", 0) or 0),
                }
        return text, usage

    try:
        return asyncio.run(_go())
    finally:
        shutil.rmtree(workdir, ignore_errors=True)


def _extract_json(text: str) -> dict:
    m = re.search(r"```(?:json)?\s*(\{.*\})\s*```", text, re.S)
    if m:
        text = m.group(1)
    else:
        start, end = text.find("{"), text.rfind("}")

"""Track T2. `firstrun run <url>`, `--targets`, `--resume`, and `firstrun report`."""

from __future__ import annotations

import os
import sys
from pathlib import Path

import click

from firstrun import config
from firstrun.models import RunState, RunStatus


def _recover_fn():
    """TODO(lead): return firstrun.recovery.recover once T4 lands. None means no recovery."""
    return None


def _verify():
    """TODO(lead): return a callable (runbook, state) -> RunStatus using firstrun.verify.verify."""
    return None


def _first_error_line(state: RunState) -> str:
    for r in reversed(state.results):
        if not r.passed:
            for text in (r.stderr, r.stdout):
                lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
                if lines:
                    return lines[-1][:120]
            return "timed out" if r.timed_out else f"exit {r.exit_code}"
    return state.stop_reason


def _summary(state: RunState, commands: dict[int, str]) -> list[str]:
    total = len(commands)
    passed = sum(1 for s in state.step_status.values() if s.value == "passed")
    if state.status == RunStatus.FAILED and state.first_failed_step is not None:
        fid = state.first_failed_step
        return [f"✗ step {fid}/{total}  {commands.get(fid, '')}  ->  {_first_error_line(state)}"]
    secs = state.time_to_first_success_s or 0
    mark = "✓" if state.status != RunStatus.FAILED else "✗"
    return [f"{mark} {state.status.value} {passed}/{total} steps, {secs:.0f} s, ${state.usage.cost_usd:.2f}"]


def _run_one(url: str, tags: list[str], resume: str | None, verify: bool) -> RunState:
    from firstrun import executor, state as state_io
    from firstrun.tracing import init_tracing

    init_tracing(tags)
    if resume:
        runbook = state_io.load_runbook(resume)
    else:
        from firstrun import planner  # built by another worker, so import late

        runbook = planner.plan(url)
    final = executor.run(runbook, run_id=resume, resume=bool(resume), tags=tags, recover=_recover_fn())
    verifier = _verify() if verify else None
    if verifier is not None and final.status == RunStatus.PASSED:
        final.status = verifier(runbook, final)
        state_io.save_state(final)
    commands = {s.id: s.command for s in runbook.steps}
    for line in _summary(final, commands):
        click.echo(line)
    click.echo(f"run dir: {state_io.run_dir(final.run_id)}")
    return final


@click.group()
def cli() -> None:
    """FirstRun: run a quickstart in a fresh container and find the step that breaks."""
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8")


@cli.command("run")
@click.argument("url", required=False)
@click.option("--targets", type=click.Path(exists=True, dir_okay=False), help="File with one URL per line.")
@click.option("--resume", "resume_id", help="Resume the run with this id.")
@click.option("--tag", "tags", multiple=True, help="Trace tag. The first one is the variant.")
@click.option("--offline", is_flag=True, help="Plan without a model.")
@click.option("--no-verify", is_flag=True, help="Skip the verification re-run.")
def run_cmd(url, targets, resume_id, tags, offline, no_verify) -> None:
    if offline:
        os.environ["FIRSTRUN_OFFLINE"] = "1"
    if not (url or targets or resume_id):
        raise click.UsageError("give a URL, --targets FILE or --resume RUN_ID")
    urls: list[str] = []
    if url:
        urls.append(url)
    if targets:
        for line in Path(targets).read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line and not line.startswith("#"):
                urls.append(line)
    from firstrun.tracing import close_tracing

    worst = 0
    try:
        if resume_id:
            final = _run_one("", list(tags), resume_id, not no_verify)
            worst = 1 if final.status == RunStatus.FAILED else 0
        for u in urls:
            final = _run_one(u, list(tags), None, not no_verify)
            if final.status == RunStatus.FAILED:
                worst = 1
    finally:
        close_tracing()
    sys.exit(worst)


@cli.command("report")
@click.option("--html", "html", is_flag=True, help="Also write an HTML report.")
def report_cmd(html) -> None:
    from firstrun import report

    click.echo(report.summary_table(config.RUNS_DIR))
    if html:
        try:
            from firstrun import report_html
        except ImportError:
            raise click.ClickException("firstrun.report_html is not built yet")
        out = Path(config.RUNS_DIR) / "report.html"
        report_html.write_html(config.RUNS_DIR, out)
        click.echo(f"html: {out}")


def main() -> None:
    cli()


if __name__ == "__main__":
    main()

"""Track T4. Small sync helpers over the Claude Agent SDK. Wrapped by neatlogs."""

from __future__ import annotations

import asyncio
import json
import os
import re
import tempfile
import threading
from typing import Any, Sequence

import claude_agent_sdk
import neatlogs

from firstrun import config

# Wrapped once. Every query shows up in the neatlogs trace.
try:
    sdk = neatlogs.wrap(claude_agent_sdk)
except Exception:  # wrapping is best effort, the plain SDK still works
    sdk = claude_agent_sdk

# A cwd outside the repo, so Entire hooks and project settings never fire.
_WORKDIR = os.path.join(tempfile.gettempdir(), "firstrun-llm")


def _cost(input_tokens: int, output_tokens: int) -> float:
    return (input_tokens * config.PRICE_INPUT_PER_MTOK + output_tokens * config.PRICE_OUTPUT_PER_MTOK) / 1_000_000


def extract_json(text: str) -> dict:
    """Pull the first JSON object out of a reply, with or without a code fence."""
    text = text.strip()
    fence = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", text, re.S)
    candidates = [fence.group(1)] if fence else []
    start = text.find("{")
    end = text.rfind("}")
    if start != -1 and end > start:
        candidates.append(text[start:end + 1])
    for c in candidates:
        try:
            value = json.loads(c)
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            return value
    raise ValueError("no JSON object in model reply")


async def _run(prompt: str, system: str, tools: Sequence[str], max_turns: int) -> tuple[str, dict]:
    config.load_env()
    os.makedirs(_WORKDIR, exist_ok=True)
    env = {k: v for k, v in os.environ.items() if k not in ("CLAUDECODE", "CLAUDE_CODE_ENTRYPOINT", "ANTHROPIC_API_KEY")}
    options = claude_agent_sdk.ClaudeAgentOptions(
        model=config.MODEL,
        effort=config.EFFORT,
        system_prompt=system,
        setting_sources=[],
        cwd=_WORKDIR,
        tools=list(tools),
        allowed_tools=list(tools),
        max_turns=max_turns,
        env=env,
    )
    text, tool_calls, usage = "", 0, {}
    async for msg in sdk.query(prompt=prompt, options=options):
        if isinstance(msg, claude_agent_sdk.AssistantMessage):
            for block in msg.content:
                if isinstance(block, claude_agent_sdk.ToolUseBlock):
                    tool_calls += 1
                elif isinstance(block, claude_agent_sdk.TextBlock):
                    text = block.text  # the last text block is the answer
        elif isinstance(msg, claude_agent_sdk.ResultMessage):
            usage = msg.usage or {}
            if msg.is_error and not text:
                raise RuntimeError(f"claude query failed: {msg.result or msg.subtype}")
            if msg.result:
                text = msg.result
    tin = int(usage.get("input_tokens", 0) or 0) + int(usage.get("cache_creation_input_tokens", 0) or 0) \
        + int(usage.get("cache_read_input_tokens", 0) or 0)
    tout = int(usage.get("output_tokens", 0) or 0)
    return text, {"input_tokens": tin, "output_tokens": tout, "tool_calls": tool_calls, "cost_usd": _cost(tin, tout)}


def _run_sync(prompt: str, system: str, tools: Sequence[str], max_turns: int) -> tuple[str, dict]:
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return asyncio.run(_run(prompt, system, tools, max_turns))
    # Already inside an event loop: run in a worker thread.
    box: dict[str, Any] = {}

    def work() -> None:
        try:
            box["out"] = asyncio.run(_run(prompt, system, tools, max_turns))
        except BaseException as exc:  # noqa: BLE001
            box["err"] = exc

    t = threading.Thread(target=work)
    t.start()
    t.join()
    if "err" in box:
        raise box["err"]
    return box["out"]


def ask(prompt: str, system: str = "", tools: Sequence[str] = (), max_turns: int = 1) -> tuple[str, dict]:
    """Plain text reply plus a usage dict."""
    return _run_sync(prompt, system, tools, max_turns)


def ask_json(prompt: str, system: str = "", tools: Sequence[str] = (), max_turns: int = 1) -> tuple[dict, dict]:
    """JSON reply plus a usage dict {input_tokens, output_tokens, tool_calls, cost_usd}."""
    system = (system + "\n\n" if system else "") + "Reply with one JSON object and nothing else."
    text, usage = _run_sync(prompt, system, tools, max_turns)
    return extract_json(text), usage

